import re
seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>')).upper()
print(len(seq))
from collections import Counter
c=Counter(seq)
print(c)
gc=sum(c[b] for b in 'GC'); print('GC%', gc/len(seq)*100)
# ORF scan
comp={'A':'T','T':'A','G':'C','C':'G'}
rc=lambda s:''.join(comp[x] for x in reversed(s))
stop={'TAA','TAG','TGA'}
def orfs(s,minlen=90):
    out=[]
    for strand,ss in (('+',s),('-',rc(s))):
        for f in range(3):
            i=f
            while i < len(ss)-2:
                if ss[i:i+3]=='ATG':
                    j=i
                    while j < len(ss)-2 and ss[j:j+3] not in stop:
                        j+=3
                    if j-i>=minlen:
                        out.append((strand,f+1,i,j-1 if False else j, j-i))
                    i=j
                else: i+=3
    return out
for o in sorted(orfs(seq),key=lambda x:-x[-1])[:20]:
    print(o)
