seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>')).upper()
L=len(seq)
comp={'A':'T','T':'A','G':'C','C':'G'}
rc=lambda s:''.join(comp[x] for x in reversed(s))
stop={'TAA','TAG','TGA'}
bases='TCAG'
aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
codon={}
i=0
for a in bases:
    for b in bases:
        for c in bases:
            codon[a+b+c]=aas[i]; i+=1
def tr(s): return ''.join(codon.get(s[i:i+3],'X') for i in range(0,len(s)-2,3))

# longest stop-free stretch per frame per strand
for name,s in (('+',seq),('-',rc(seq))):
    for f in range(3):
        best=[]
        cur_start=None
        for j in range(f,L-2,3):
            if s[j:j+3] in stop:
                if cur_start is not None:
                    best.append((cur_start,j))
                cur_start=None
            else:
                if cur_start is None: cur_start=j
        if cur_start is not None: best.append((cur_start,L-3+((L-f)%3)))
        if best:
            b=max(best,key=lambda x:x[1]-x[0])
            print(name,f+1,'longest stopfree',b,b[1]-b[0],'starts with ATG?',s[b[0]:b[0]+3])
