import re
seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>')).upper()
L=len(seq)
comp={'A':'T','T':'A','G':'C','C':'G'}
rc=lambda s:''.join(comp[x] for x in reversed(s))
# common motifs
motifs={'Chi':'GCTGGTGG','-10':'TATAAT','-35':'TTGACA','SD':'AGGAGG','ter?':'GGGGGG',
        'EcoRI':'GAATTC','BamHI':'GGATCC','PstI':'CTGCAG','XhoI':'CTCGAG','HindIII':'AAGCTT'}
for n,m in motifs.items():
    print(n,m,[mm.start()+1 for mm in re.finditer(m,seq)])
# palindromes / inverted repeats scan: length>=8 with perfect revcomp within 500
def pal(rmin=8):
    out=[]
    for i in range(L-rmin):
        for ln in range(rmin,30):
            if i+ln>L: break
            s=seq[i:i+ln]
            if s==rc(s):
                out.append((i+1,ln))
    return out
# simpler: find all palindromic words of len 8-14
for ln in (8,10,12):
    ps=[i+1 for i in range(L-ln+1) if seq[i:i+ln]==rc(seq[i:i+ln])]
    print('pal len',ln,ps[:20],'count',len(ps))
# homopolymers
print('homopolymers >=6:')
for m in re.finditer(r'(A{6,}|T{6,}|G{6,}|C{6,})',seq):
    print('  ',m.start()+1, m.group())
"}

